examples.code:
VStack(alignment: .leading) {
    MonarchUptimeBar("API", segments: days, size: .sm, activeIndex: $active)
    MonarchUptimeBar("Website", segments: days, size: .sm, activeIndex: $active)
}

examples.setup:
@State private var active: Int? = 3
private let days: [MonarchUptimeBarSegment] = (1...14).map {
    MonarchUptimeBarSegment(id: "\($0)", label: "Day \($0)", status: $0 == 4 ? .down : .operational)
}
